mapper.select:
/* * SQL-ID : isry.couns.mngr.etxpyreqstdmng.mapper.NgtmWorkEtxpyReqstdMngMapper.selectNgtmWorkEtxpyReqstdMngList : 야간수당신청서 LIST * 작성자 : 2023.05.16 - Jeong.Won.Je * 탈퇴한 종사자의 SAB230 데이터 삭제로 인한 상담원 목록 조회시 이슈 발생으로 상담원 목록 조회 쿼리 변경 * 2023.07.06 수정 - Jeong.Won.Je * SCA100의 DEL_YN = 'N' 조건 삭제 * 2023.07.07 수정 - Jeong.Won.Je */ WITH ZZ AS ( SELECT * FROM ( SELECT T1.USER_ID AS USER_ID , T1.ENFSN_NO AS ENFSN_NO , NVL(T2.RETIRE_YMD, TO_CHAR(SYSDATE, 'YYYYMMDD')) AS RETIRE_YMD FROM SAA200 T1 , SCA100 T2 WHERE 1=1 AND T2.OGDP_INST_NO = '1000000947' AND T1.ENFSN_NO = T2.ENFSN_NO AND NOT EXISTS ( SELECT * FROM SAB230 T3 WHERE T3.USER_ID = T1.USER_ID AND T3.GROUP_AUTHRT_SE_CD != '340' ) )
WHERE RETIRE_YMD > #{YYYYMMDD}
) , PENSN AS ( SELECT NIGHT_WORK_UNTPC_AMT , WIK_OVTIME_UNTPC_AMT , NIGHT_OVTIME_UNTPC_AMT FROM AYC380 WHERE 1=1 AND CRTR_YR = SUBSTR(#{yyyyMm}, 0, 4) ) , NIGHT AS ( SELECT ZZ.USER_ID AS USER_ID , C##RG.DEC_B64(B4.FLNM_ENCPT) AS USER_FLNM , B1.WORK_YMD AS WORK_YMD
, CASE WHEN B2.BGNG_HR > '18:00' THEN CASE WHEN B2.END_HR > '22:00' THEN FLOOR((TO_DATE(B1.WORK_YMD || REPLACE(B2.END_HR, ':', '') || '00', 'YYYY-MM-DD HH24MISS') - TO_DATE(B1.WORK_YMD || '220000', 'YYYY-MM-DD HH24MISS')) * 24 * 60) WHEN B2.END_HR <= '02:00' THEN FLOOR(((TO_DATE(B1.WORK_YMD || REPLACE(B2.END_HR, ':', '') || '00', 'YYYY-MM-DD HH24MISS') + 1) - TO_DATE(B1.WORK_YMD || '220000', 'YYYY-MM-DD HH24MISS')) * 24 * 60) WHEN B2.END_HR > '02:00' AND B2.END_HR < '04:00' THEN FLOOR(((TO_DATE(B1.WORK_YMD || REPLACE(B2.END_HR, ':', '') || '00', 'YYYY-MM-DD HH24MISS') + 1) - TO_DATE(B1.WORK_YMD || REPLACE(B2.BGNG_HR, ':', '') || '00', 'YYYY-MM-DD HH24MISS')) * 24 * 60) ELSE 0 END WHEN B2.BGNG_HR < '06:00' THEN CASE WHEN B2.END_HR >= '04:00' AND B2.END_HR <= '06:00' THEN FLOOR((TO_DATE(B1.WORK_YMD || REPLACE(B2.END_HR, ':', '') || '00', 'YYYY-MM-DD HH24MISS') - TO_DATE(B1.WORK_YMD || REPLACE(B2.BGNG_HR, ':', '') || '00', 'YYYY-MM-DD HH24MISS')) * 24 * 60) WHEN B2.END_HR > '06:00' AND B2.END_HR < '10:00' THEN FLOOR((TO_DATE(B1.WORK_YMD || '060001', 'YYYY-MM-DD HH24MISS') - TO_DATE(B1.WORK_YMD || REPLACE(B2.BGNG_HR, ':', '') || '00', 'YYYY-MM-DD HH24MISS')) * 24 * 60) ELSE 0 END ELSE 0 END AS WTIME
, ( SELECT COUNT(*) FROM ( SELECT C1.USER_ID , C1.VCATN_SE_CD , C1.VCATN_BGNG_YMD , C1.VCATN_END_YMD FROM AYC130 C1 WHERE 1=1 AND C1.USER_ID = B1.USER_ID AND C1.DEL_YN = 'N' AND C1.APLY_SE_CD = '01' AND C1.APRV_STTS_SE_CD = '2' AND B1.WORK_YMD BETWEEN C1.VCATN_BGNG_YMD AND C1.VCATN_END_YMD GROUP BY C1.USER_ID, C1.VCATN_SE_CD, C1.VCATN_BGNG_YMD, C1.VCATN_END_YMD ) ) AS VCATN_YN FROM ZZ , AYC100 B1 , AYC110 B2 , SCA100 B4 WHERE 1=1 AND SUBSTR(B1.WORK_YMD, 0, 6) = #{yyyyMm} AND B1.USER_ID = ZZ.USER_ID AND B1.DEL_YN = 'N' AND B2.BIZ_PLAN_MNG_NO = B1.BIZ_PLAN_MNG_NO AND B2.DEL_YN = 'N' AND B4.ENFSN_NO = ZZ.ENFSN_NO ) SELECT NVL(APRV_TB.CONSTT_ID, INQ_TB.USER_ID) AS USER_ID , INQ_TB.USER_FLNM AS USER_FLNM , NVL(APRV_TB.NIGHT_WORK_HR, INQ_TB.NIGHT_WORK_HR) AS NIGHT_WORK_HR , NVL(APRV_TB.PENSN_SUM_AMT, INQ_TB.PENSN_SUM_AMT) AS PENSN_SUM_AMT , NVL(APRV_TB.APRV_YN, 'N') AS APRV_YN FROM ( SELECT TT1.USER_ID , TT1.USER_FLNM , TT1.NIGHT_WORK_HR , TRUNC(TT1.NIGHT_WORK_HR / 60 * TT2.NIGHT_WORK_UNTPC_AMT, -1) AS PENSN_SUM_AMT FROM ( SELECT USER_ID , USER_FLNM , TRUNC(SUM(WTIME), -1) AS NIGHT_WORK_HR FROM NIGHT WHERE 1=1
AND WTIME >= 0
AND VCATN_YN = 0 GROUP BY USER_ID, USER_FLNM ) TT1 , PENSN TT2 ) INQ_TB LEFT OUTER JOIN ( SELECT * FROM AYC350 WHERE GIVE_YM = #{yyyyMm} ) APRV_TB ON INQ_TB.USER_ID = APRV_TB.CONSTT_ID ORDER BY INQ_TB.USER_FLNM ASC

/* * SQL-ID : isry.couns.mngr.etxpyreqstdmng.mapper.NgtmWorkEtxpyReqstdMngMapper.selectNgtmWorkEtxpyReqstdMngDetail1 : 야간수당신청서상세 LIST * 작성자 : 2023.05.16 - Jeong.Won.Je * SCA100의 DEL_YN = 'N' 조건 삭제 * 2023.07.07 수정 - Jeong.Won.Je */ WITH PENSN AS ( SELECT NIGHT_WORK_UNTPC_AMT , WIK_OVTIME_UNTPC_AMT , NIGHT_OVTIME_UNTPC_AMT FROM AYC380 WHERE 1=1 AND CRTR_YR = SUBSTR(#{YYYYMM}, 0, 4) ) , NIGHT AS ( SELECT A1.USER_ID AS USER_ID , C##RG.DEC_B64(A4.FLNM_ENCPT) AS USER_FLNM , A1.WORK_YMD AS WORK_YMD
, CASE WHEN A2.BGNG_HR > '18:00' THEN CASE WHEN A2.END_HR > '22:00' THEN FLOOR((TO_DATE(A1.WORK_YMD || REPLACE(A2.END_HR, ':', '') || '00', 'YYYY-MM-DD HH24MISS') - TO_DATE(A1.WORK_YMD || '220000', 'YYYY-MM-DD HH24MISS')) * 24 * 60) WHEN A2.END_HR <= '02:00' THEN FLOOR(((TO_DATE(A1.WORK_YMD || REPLACE(A2.END_HR, ':', '') || '00', 'YYYY-MM-DD HH24MISS') + 1) - TO_DATE(A1.WORK_YMD || '220000', 'YYYY-MM-DD HH24MISS')) * 24 * 60) WHEN A2.END_HR > '02:00' AND A2.END_HR < '04:00' THEN FLOOR(((TO_DATE(A1.WORK_YMD || REPLACE(A2.END_HR, ':', '') || '00', 'YYYY-MM-DD HH24MISS') + 1) - TO_DATE(A1.WORK_YMD || REPLACE(A2.BGNG_HR, ':', '') || '00', 'YYYY-MM-DD HH24MISS')) * 24 * 60) ELSE 0 END WHEN A2.BGNG_HR < '06:00' THEN CASE WHEN A2.END_HR >= '04:00' AND A2.END_HR <= '06:00' THEN FLOOR((TO_DATE(A1.WORK_YMD || REPLACE(A2.END_HR, ':', '') || '00', 'YYYY-MM-DD HH24MISS') - TO_DATE(A1.WORK_YMD || REPLACE(A2.BGNG_HR, ':', '') || '00', 'YYYY-MM-DD HH24MISS')) * 24 * 60) WHEN A2.END_HR > '06:00' AND A2.END_HR < '10:00' THEN FLOOR((TO_DATE(A1.WORK_YMD || '060001', 'YYYY-MM-DD HH24MISS') - TO_DATE(A1.WORK_YMD || REPLACE(A2.BGNG_HR, ':', '') || '00', 'YYYY-MM-DD HH24MISS')) * 24 * 60) ELSE 0 END ELSE 0 END AS WTIME
, A2.BGNG_HR || ' ~ ' || A2.END_HR || ' 근무' AS BIGO , ( SELECT COUNT(*) FROM ( SELECT C1.USER_ID , C1.VCATN_SE_CD , C1.VCATN_BGNG_YMD , C1.VCATN_END_YMD FROM AYC130 C1 WHERE 1=1 AND C1.USER_ID = A1.USER_ID AND C1.DEL_YN = 'N' AND C1.APLY_SE_CD = '01' AND C1.APRV_STTS_SE_CD = '2' AND A1.WORK_YMD BETWEEN C1.VCATN_BGNG_YMD AND C1.VCATN_END_YMD GROUP BY C1.USER_ID, C1.VCATN_SE_CD, C1.VCATN_BGNG_YMD, C1.VCATN_END_YMD ) ) AS VCATN_YN FROM AYC100 A1 , AYC110 A2 , SAA200 A3 , SCA100 A4 WHERE 1=1 AND A1.USER_ID = #{USER_ID} AND SUBSTR(A1.WORK_YMD, 0, 6) = #{YYYYMM} AND A1.DEL_YN = 'N' AND A2.BIZ_PLAN_MNG_NO = A1.BIZ_PLAN_MNG_NO AND A2.DEL_YN = 'N' AND A3.USER_ID = A1.USER_ID AND A4.ENFSN_NO = A3.ENFSN_NO ) SELECT NIGHT.USER_ID AS USER_ID , NIGHT.USER_FLNM AS USER_FLNM , NIGHT.WORK_YMD AS WORK_YMD , NIGHT.WTIME AS WTIME , NIGHT.BIGO AS BIGO , NIGHT.VCATN_YN AS VCATN_YN , SUM(NIGHT.WTIME) OVER() AS SSUM , TRUNC(SUM(NIGHT.WTIME) OVER() / 60 * PENSN.NIGHT_WORK_UNTPC_AMT, -1) AS AAMT FROM NIGHT , PENSN WHERE 1=1 AND NIGHT.VCATN_YN = 0 AND NOT NIGHT.WTIME = 0 ORDER BY NIGHT.WORK_YMD ASC

mapper.update:
UPDATE  AYC350      AA      /* 야간근무수당 */
SET
        RM_CN           =       #{BIGO}
    ,   LAST_MDFR_ID    =       #{USER_ID}
    ,   LAST_MDFCN_DT   =       SYSDATE            
WHERE   1=1
    AND AA.GIVE_YM      =       #{GIVE_YM}
    AND AA.CONSTT_ID    =       #{CONSTT_ID}
    AND AA.DEL_YN       =       'N'
